mapper.select:
SELECT mao.id, mao.shop_id, shop.poi_id, mao.order_id, mao.order_view_id, mao.app_id, mao.service_code, mao.pay_status, mao.version, mao.version_name, mao.days, mao.right_status, mao.real_pay_price, mao.type, mao.address, mao.shop_name, mao.phone, CASE WHEN mao.start_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.start_time) END AS start_time_at, CASE WHEN mao.end_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.end_time) END AS end_time_at, CASE WHEN mao.order_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.order_time) END AS order_time_at, mao.create_time, mao.update_time FROM mt_app_order mao LEFT JOIN mt_shop shop ON shop.id = mao.shop_id WHERE mao.shop_id IS NOT NULL
AND mao.order_id LIKE CONCAT('%', #{orderId}, '%')
AND mao.order_view_id LIKE CONCAT('%', #{orderViewId}, '%')
AND shop.poi_id LIKE CONCAT('%', #{poiId}, '%')
AND mao.shop_name LIKE CONCAT('%', #{shopName}, '%')
AND mao.pay_status = #{payStatus}
AND mao.right_status = #{rightStatus}
AND mao.version = #{version}
AND mao.version_name = #{versionName}
AND mao.order_time >= #{orderStartTime}
AND mao.order_time <= #{orderEndTime}
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id = #{targetUserId} )
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id = #{currentUserId} )
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id IN
#{userId}
)
ORDER BY mao.order_time DESC, mao.id DESC

SELECT DISTINCT mao.version AS version, mao.version_name AS versionName FROM mt_app_order mao WHERE mao.shop_id IS NOT NULL AND mao.version IS NOT NULL AND mao.version != ''
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id = #{currentUserId} )
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id IN
#{userId}
)
ORDER BY mao.version ASC, mao.version_name ASC

SELECT mao.id, mao.shop_id, shop.poi_id, mao.order_id, COALESCE(NULLIF(shop.contact_phone, ''), NULLIF(shop.phone, ''), NULLIF(mao.phone, '')) AS phone, mao.pay_status, mao.version, mao.version_name, mao.days, mao.real_pay_price, mao.shop_name, CASE WHEN mao.start_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.start_time) END AS start_time_at, CASE WHEN mao.end_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.end_time) END AS end_time_at, CASE WHEN mao.order_time IS NULL THEN NULL ELSE FROM_UNIXTIME(mao.order_time) END AS order_time_at FROM mt_app_order mao LEFT JOIN mt_shop shop ON shop.id = mao.shop_id WHERE mao.shop_id IS NOT NULL AND mao.pay_status = #{paidPayStatus} AND mao.real_pay_price > 0 AND mao.start_time IS NOT NULL AND mao.end_time IS NOT NULL AND mao.start_time <= #{serviceEndTime} AND mao.end_time >= #{serviceStartTime}
AND shop.poi_id = #{poiId}
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id = #{currentUserId} )
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = mao.shop_id AND usb.user_id IN
#{userId}
)
ORDER BY mao.order_time DESC, mao.id DESC

mapper.insert:
INSERT INTO mt_app_order (
    order_id, order_view_id, app_id, service_code, pay_status, version, version_name, days,
    start_time, end_time, right_status, real_pay_price, order_time, create_time, update_time,
    type, address, shop_name, phone, shop_id
) VALUES (
    #{orderId}, #{orderViewId}, #{appId}, #{serviceCode}, #{payStatus}, #{version}, #{versionName},
    #{days}, #{startTime}, #{endTime}, #{rightStatus}, #{realPayPrice}, #{orderTime}, #{createTime},
    #{updateTime}, #{type}, #{address}, #{shopName}, #{phone}, #{shopId}
)
